gate_travel_settle.script:
if(!skip){const G={"relstaris":["Relstaris","Grand Lunar Gate Hub","<O> Gate"],"solvraxis":["Solvraxis","Lunar Gate District","<O> Gate Platform"],"korrvane":["Korrvane","The Gate Plazas"],"helvyra":["Helvyra","Helvyra Lunar Gate Hub","Arrival Ring"],"quilrath":["Quilrath","The Quilrath Gate","The Arrival Processing"],"ignivex":["Ignivex","Ignivex Lunar Gate","The Gate Platform"],"vexorath":["Vexorath","Vexorath Gate District","Public Lunar Gate Platform"],"dustfall":["Dustfall","Lunar Gate Yard","Arrival Platform"]};
const S={"quilrath":["rep.house_dravon",10,"the Quilrath Gate is Dravon territory, and without at least basic standing with House Dravon the security detail turns the party away at the staging area: compliance first, travel second."],"vexorath":["rep.house_genesis",10,"departing Vexorath through the gate requires security clearance, and the Genesis officers at the departure concourse will not pass the party without a baseline of standing with House Genesis."]};
const F={"helvyra":["event.running.helvyra_gate_failure",["solvraxis","korrvane","vexorath"],"a gate fitting at the Helvyra hub has failed with a burned relay, stranding the Solvraxis, Korrvane and Vexorath routes until it is replaced."]};
function why(r,o,d){if(r==='route')return 'there is no direct Lunar Gate route from '+G[o][0]+' to '+G[d][0]+'; travellers for '+G[d][0]+' change at the Grand Lunar Gate Hub in Relstaris.';if(r==='unregistered')return 'the departure boards list '+G[d][0]+' but mark it as requiring prior registration: the party has never arrived at '+G[d][1]+', so the gate will not send them there yet.';if(r==='standing'&&S[o])return S[o][2];if(r==='failure'&&F[o])return F[o][2];return 'the gate refuses that destination.';}
function arrivalArea(o,d){return G[d][2]?G[d][2].replace('<O>',G[o][0]):'';}
const A={"Grand Lunar Gate Hub":["Solvraxis Gate","Korrvane Gate","Quilrath Gate","Vexorath Gate","Helvyra Gate","Ignivex Gate","Dustfall Gate","Regional Transfer Gates","Main Arrival Concourse","Grand Departure Hall","Diplomatic Transit Court","Academy Arrival Hall","Visitor Orientation Center","Family Reception Court","Lost Property Hall","Emergency Medical Station","City Transit Exchange","Public Waiting Gardens","Restricted Movement Control","Contair Maintenance Annex","Security Review Court","Emergency Isolation Platforms","Worker Shift Hall","Gate Records Office","Platform Dispute Desk"],"Lunar Gate District":["Relstaris Gate Platform","Korrvane Gate Platform","Helvyra Gate Platform","Arrival Orientation Hall","Visitor Waiting Court","Gate Security Peace Line","Orvessa Guest Reception Desk","Restricted Transit Control"],"The Gate Plazas":["Upper Gate Plaza","Mid Gate Plaza","Lower Gate Plaza","Tournament Day Overflow","Visitor Orientation Deck","Contair Maintenance Alcove","Corsair Shipment Lockers"],"Helvyra Lunar Gate Hub":["Arrival Ring","Departure Concourse","Compact Inspection Lanes","Hub Scheduling Office","Contair Inspection Post","Traveller Orientation Deck"],"The Quilrath Gate":["Quilrath Gate Yard","The Legacy Gate Structure","The Inspection Floor","The Engineer Stations","The Arrival Processing"],"Ignivex Lunar Gate":["The Gate Platform","The Heat-Armored Security Line","The Volen Civic Post","Emergency Lockdown Control","The Relstaris Approach","The Dustfall Approach","The Arrival Hall","The Watch Rooms"],"Vexorath Gate District":["Public Lunar Gate Platform","Arrival Diagnostic Lane","Visitor Authentication Hall","Cargo Calibration Court","Gate Maintenance Gallery","Transit Delay Alcove","Contair Travel Office","Dravon Access Denial Marker"],"Lunar Gate Yard":["Main Lunar Gate","Patched Stabilizer Ring","Arrival Platform","Local Repair Console","Unregistered Arrival Bench","Cargo Transfer Strip","Emergency Shutdown Lever","Old Contair Service Alcove","Gate Component Lockup"]};
const loc=String(check({type:'party-location'})||''),area=String(check({type:'party-area'})||'');
let fl=loc,fa=area;
const p=String(check({type:'read-string',key:'gate.hold'})||'').split('|');
if(p.length>=6){effects.push({type:'write-string',key:'gate.hold',operator:'set',value:'-'});
const k=p[0],o=p[1],d=p[2],r=p[3],tk=Number(p[5]);
if(!G[o]||!G[d]||(k!=='arrive'&&k!=='refuse')){log('[LUNAR GATE] settle: unreadable hold '+p.join('|'));}
else if(tk!==(Number(check({type:'game-tick'}))||0)){log('[LUNAR GATE] settle: stale hold from tick '+p[5]+' cleared');}
else{const want=k==='arrive'?G[d][1]:G[o][1];
if(loc===want){log('[LUNAR GATE] settle: party at '+loc+' as the gate decided');}
else{effects.push({type:'party-location',operator:'set',value:want});fl=want;
if(k==='arrive'){const a=arrivalArea(o,d);fa=a||A[want][0];effects.push({type:'party-area',operator:'set',value:fa});effects.push({type:'story',instruction:'The Lunar Gate delivered the party to '+fa+' in '+G[d][1]+', '+G[d][0]+', and they are there now. Continue from the arrival.'});}
else{const q=String(check({type:'read-string',key:'gate.area'})||'').split('|');fa=(q[0]===want&&A[want].indexOf(q[1])>=0)?q[1]:A[want][0];effects.push({type:'party-area',operator:'set',value:fa});effects.push({type:'story',instruction:'The Lunar Gate never sent the party to '+G[d][0]+': '+why(r,o,d)+' Whatever seemed to begin in the gate light, the transfer aborted and the party is still at '+fa+' in '+G[o][1]+', '+G[o][0]+'. Continue from there.'});}
log('[LUNAR GATE] settle: party was at '+loc+' ('+area+'), set to '+want+' ('+fa+')');}}}
if(A[fl]&&A[fl].indexOf(fa)>=0){const v=fl+'|'+fa;if(String(check({type:'read-string',key:'gate.area'})||'')!==v){effects.push({type:'write-string',key:'gate.area',operator:'set',value:v});}}
if(!effects.length){skip=true;}}

city_transit_settle.script:
if(!skip){const loc=String(check({type:'party-location'})||''),area=String(check({type:'party-area'})||'');
const tick=Number(check({type:'game-tick'}))||0;let fl=loc;
const hd=String(check({type:'read-string',key:'transit.hold'})||'');
if(hd&&hd!=='-'){effects.push({type:'write-string',key:'transit.hold',operator:'set',value:'-'});const d=String(check({type:'read-string',key:'transit.dest'})||''),da=String(check({type:'read-string',key:'transit.darea'})||'');
if(Number(hd)===tick&&d&&loc!==d){if(!loc||loc==='Wilderness'){effects.push({type:'party-location',operator:'set',value:d});if(da){effects.push({type:'party-area',operator:'set',value:da});}
effects.push({type:'story',instruction:'The party is at '+(da?da+' in ':'')+d+', where the short crossing of the city ended; continue from there.'});fl=d;
log('[CITY TRANSIT] settle: party was at '+(loc||'nowhere')+(area?' ('+area+')':'')+', set to '+d+(da?' ('+da+')':''));}
else{log('[CITY TRANSIT] settle: the engine stopped the party at '+loc+(area?' ('+area+')':'')+' on the way to '+d+'; left there with the narration');}}}
if(fl&&fl!=='Wilderness'&&String(check({type:'read-string',key:'transit.from'})||'')!==fl){effects.push({type:'write-string',key:'transit.from',operator:'set',value:fl});}
if(!effects.length){skip=true;}}

gate_travel_from_relstaris.script:
if(!skip){const O="relstaris";
const R=["solvraxis","korrvane","helvyra","quilrath","ignivex","vexorath","dustfall"];
const AO=["Solvraxis Gate","Korrvane Gate","Quilrath Gate","Vexorath Gate","Helvyra Gate","Ignivex Gate","Dustfall Gate","Regional Transfer Gates","Main Arrival Concourse","Grand Departure Hall","Diplomatic Transit Court","Academy Arrival Hall","Visitor Orientation Center","Family Reception Court","Lost Property Hall","Emergency Medical Station","City Transit Exchange","Public Waiting Gardens","Restricted Movement Control","Contair Maintenance Annex","Security Review Court","Emergency Isolation Platforms","Worker Shift Hall","Gate Records Office","Platform Dispute Desk"];
const G={"relstaris":["Relstaris","Grand Lunar Gate Hub","<O> Gate"],"solvraxis":["Solvraxis","Lunar Gate District","<O> Gate Platform"],"korrvane":["Korrvane","The Gate Plazas"],"helvyra":["Helvyra","Helvyra Lunar Gate Hub","Arrival Ring"],"quilrath":["Quilrath","The Quilrath Gate","The Arrival Processing"],"ignivex":["Ignivex","Ignivex Lunar Gate","The Gate Platform"],"vexorath":["Vexorath","Vexorath Gate District","Public Lunar Gate Platform"],"dustfall":["Dustfall","Lunar Gate Yard","Arrival Platform"]};
const S={};
const F={};
function why(r,o,d){if(r==='route')return 'there is no direct Lunar Gate route from '+G[o][0]+' to '+G[d][0]+'; travellers for '+G[d][0]+' change at the Grand Lunar Gate Hub in Relstaris.';if(r==='unregistered')return 'the departure boards list '+G[d][0]+' but mark it as requiring prior registration: the party has never arrived at '+G[d][1]+', so the gate will not send them there yet.';if(r==='standing'&&S[o])return S[o][2];if(r==='failure'&&F[o])return F[o][2];return 'the gate refuses that destination.';}
function arrivalArea(o,d){return G[d][2]?G[d][2].replace('<O>',G[o][0]):'';}
const t=[].concat(check({type:'action-text'})||[]).join(' ').toLowerCase();
let d=null,at=-1;
for(const k in G){if(k===O)continue;const m=new RegExp('\\b'+k+'\\b').exec(t);if(m&&(at<0||m.index<at)){d=k;at=m.index;}}
const h=G[O];
if(!d){skip=true;log('[LUNAR GATE] departure at '+O+' names no other city; skipped');}
else{let r='';
if(R.indexOf(d)<0){r='route';}
else if(F[O]&&F[O][1].indexOf(d)>=0&&check({type:'read-boolean',key:F[O][0]})===true){r='failure';}
else if((Number(check({type:'read-number',key:'gate.'+d}))||0)<1){r='unregistered';}
else if(S[O]&&(Number(check({type:'read-number',key:S[O][0]}))||0)<S[O][1]){r='standing';}
const tick=Number(check({type:'game-tick'}))||0;
if(r){const w=why(r,O,d);const cl=String(check({type:'party-location'})||''),ca=String(check({type:'party-area'})||'');if(cl!==h[1]||AO.indexOf(ca)<0){const q=String(check({type:'read-string',key:'gate.area'})||'').split('|');const ba=(q[0]===h[1]&&AO.indexOf(q[1])>=0)?q[1]:AO[0];effects.push({type:'party-location',operator:'set',value:h[1]});effects.push({type:'party-area',operator:'set',value:ba});log('[LUNAR GATE] the engine had already moved the party to '+cl+' ('+ca+'); returned to '+h[1]+' ('+ba+') before narration');}effects.push({type:'story',instruction:'Even if the attempt itself succeeds, '+w+' No transfer opens. Narrate the refusal and keep the party at '+h[1]+'; do not narrate a departure or an arrival elsewhere.'});effects.push({type:'write-string',key:'gate.hold',operator:'set',value:['refuse',O,d,r,'',tick].join('|')});log('[LUNAR GATE] refused '+O+' -> '+d+' ('+r+')');}
else{const a=arrivalArea(O,d);effects.push({type:'party-location',operator:'set',value:G[d][1]});if(a){effects.push({type:'party-area',operator:'set',value:a});}effects.push({type:'story',instruction:'The party has just travelled by Lunar Gate from '+h[1]+' in '+h[0]+' to '+G[d][1]+' in '+G[d][0]+'. Narrate the boarding and the gate activation briefly, then open on arrival'+(a?' at '+a:'')+' in '+G[d][1]+'. A gate skips the journey: there is no memory of the land between the cities.'});effects.push({type:'write-string',key:'gate.hold',operator:'set',value:['arrive',O,d,'','',tick].join('|')});log('[LUNAR GATE] '+O+' -> '+d+': party-location set to '+G[d][1]+(a?', area '+a:''));}}}

